using System;
using System.Collections;
using System.Collections.Generic;
using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "SkyPiercerEffect", menuName = "Data/Battle/Effects/Austra/SkyPiercer Effect")]
public class SkyPiercerEffect : Effect
{
	[Header("Sky Piercer Effect")]
	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	[SerializeField]
	private float timeBetweenPurifiesVFX;

	[SerializeField]
	private float timeBetweenPurifies;

	[SerializeField]
	private PurifyAction purifyAction;

	[NonSerialized]
	private int timesAmount;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		return Smart.Format(GetLocalizedDescription(), base.localizationManager.GetLocalizedWhereXTimes(purifyAction.GetActionDescription(amount).RemoveLast(), amount == EffectsValues.NO_VALUE, "", removeThirdArgument: true)) + AppendedDescription();
	}

	protected override string AppendedDescription()
	{
		return "\n" + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedThisPurifyCanTriggerCritical();
	}

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		timesAmount = 0;
	}

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		if (timesAmount == 0)
		{
			ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(PurifyRandomEnemy(effectAmount, effectOwner));
			ReferenceSingleton<GameStateManager>.Instance.SetState(ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState);
		}
		timesAmount++;
		return effectAmount;
	}

	private IEnumerator PurifyRandomEnemy(int purifyAmount, GameObject effectOwner)
	{
		yield return new WaitForSeconds(0.05f);
		List<GameObject> targets = currentCorruptedAnimals.activeCorruptedAnimals;
		if (currentCorruptedAnimals.activeCorruptedAnimals.Count > 0)
		{
			PlayerEffects playerEffects = effectOwner.GetComponent<PlayerEffects>();
			playerEffects.IsEffectActive(this, activateFeedback: true, enqueueFeedback: false);
			yield return new WaitForSeconds(0.3f);
			for (int i = 0; i < timesAmount; i++)
			{
				if (targets.Count > 0)
				{
					GameObject target = targets.PickRandom();
					if (IsVFXEnabled())
					{
						PlayEffectActivationSFX();
						SpawnVFX(GetVFXOwnerPosition(target), 3f);
						yield return new WaitForSeconds(timeBetweenPurifiesVFX);
					}
					effectOwner.GetComponent<PlayerSpriteControl>().PlayAnimationForced(AnimationType.Attack, AnimationChangeType.ReturnToIdleAnimation);
					int amount = playerEffects.IsPlayerCriticalCheckCritical(purifyAmount, fierceSquall: false, sentPur: false);
					target.GetComponent<CorruptionStats>().Purify(amount, null, CorruptionPurifyModifierEnum.NONE, playSFX: true);
					if (!IsVFXEnabled() && i < timesAmount - 1)
					{
						yield return new WaitForSeconds(timeBetweenPurifies);
					}
				}
			}
		}
		timesAmount = 0;
	}
}
